sed -i "/button.setAttribute('aria-pressed', String(favorite));/d" 'src/pages/books/[slug].astro'
cat > src/pages/contact.astro <<'EOF'
---
import Layout from '../layouts/Layout.astro';
import { normalize, successMessage, validate, type ContactErrors, type ContactValues } from '../lib/contact';

export const prerender = false;

let values: ContactValues = { name: '', email: '', message: '' };
let errors: ContactErrors = {};
let success: string | null = null;

if (Astro.request.method === 'POST') {
  let data: FormData | null = null;
  try {
    data = await Astro.request.formData();
  } catch {
    data = null;
  }
  const field = (key: string) => {
    const value = data?.get(key);
    return typeof value === 'string' ? value : '';
  };
  values = { name: field('name'), email: field('email'), message: field('message') };
  errors = validate(values);
  const valid = Object.keys(errors).length === 0;

  if (Astro.request.headers.get('accept')?.includes('application/json')) {
    return Response.json(
      valid ? { ok: true, message: successMessage(values.name) } : { ok: false, errors },
      { status: valid ? 200 : 400 },
    );
  }

  if (valid) {
    success = successMessage(normalize(values).name);
    values = { name: '', email: '', message: '' };
  } else {
    Astro.response.status = 400;
  }
}
---

<Layout title="Contact | Bookshelf">
  <h1>Contact</h1>
  <p id="contact-status" role="status" hidden={!success}>{success}</p>
  <form method="post" action="/contact" novalidate id="contact-form">
    <div class="field">
      <label for="name">Name</label>
      <input
        type="text"
        id="name"
        name="name"
        value={values.name}
        aria-describedby="name-error"
        aria-invalid={errors.name ? 'true' : undefined}
      />
      <span class="error" id="name-error" data-error-for="name">{errors.name}</span>
    </div>
    <div class="field">
      <label for="email">Email</label>
      <input
        type="email"
        id="email"
        name="email"
        value={values.email}
        aria-describedby="email-error"
        aria-invalid={errors.email ? 'true' : undefined}
      />
      <span class="error" id="email-error" data-error-for="email">{errors.email}</span>
    </div>
    <div class="field">
      <label for="message">Message</label>
      <textarea
        id="message"
        name="message"
        rows="5"
        aria-describedby="message-error"
        aria-invalid={errors.message ? 'true' : undefined}>{values.message}</textarea>
      <span class="error" id="message-error" data-error-for="message">{errors.message}</span>
    </div>
    <button type="submit">Send</button>
  </form>
</Layout>

<script>
  import { successMessage, validate, type ContactErrors, type ContactValues } from '../lib/contact';

  const form = document.querySelector<HTMLFormElement>('#contact-form');
  const status = document.querySelector<HTMLElement>('#contact-status');

  if (form && status) {
    const fields = ['name', 'email', 'message'] as const;

    const showErrors = (errors: ContactErrors) => {
      for (const key of fields) {
        const message = errors[key] ?? '';
        const target = form.querySelector<HTMLElement>(`[data-error-for="${key}"]`);
        if (target) target.textContent = message;
        const input = form.elements.namedItem(key);
        if (input instanceof HTMLElement) {
          if (message) input.setAttribute('aria-invalid', 'true');
          else input.removeAttribute('aria-invalid');
        }
      }
    };

    const showStatus = (text: string | null) => {
      status.textContent = text ?? '';
      status.hidden = !text;
    };

    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      const data = new FormData(form);
      const values: ContactValues = {
        name: String(data.get('name') ?? ''),
        email: String(data.get('email') ?? ''),
        message: String(data.get('message') ?? ''),
      };
      const errors = validate(values);
      showErrors(errors);
      showStatus(null);
      if (Object.keys(errors).length > 0) {
        const first = fields.find((key) => errors[key]);
        const input = first ? form.elements.namedItem(first) : null;
        if (input instanceof HTMLElement) input.focus();
        return;
      }

      try {
        const response = await fetch(form.action, {
          method: 'POST',
          body: new URLSearchParams(data as unknown as Record<string, string>),
          headers: { Accept: 'application/json' },
        });
        const result: { ok: boolean; message?: string; errors?: ContactErrors } =
          await response.json();
        if (result.ok) {
          form.reset();
          showStatus(result.message ?? successMessage(values.name));
        } else {
          showErrors(result.errors ?? {});
        }
      } catch {
        form.submit();
      }
    });
  }
</script>

<style>
  .field {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    margin-bottom: 1rem;
  }
  .error {
    color: #b00020;
  }
  input,
  textarea {
    font: inherit;
    padding: 0.4rem;
    max-width: 30rem;
  }
  #contact-status {
    padding: 0.5rem;
    background: #e6f4ea;
    border: 1px solid #2e7d32;
  }
</style>
EOF
